package com.example.bank.web;

import static org.junit.jupiter.api.Assertions.assertEquals;

import com.example.bank.AccountRepository;
import com.example.bank.AccountService;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;
import org.junit.jupiter.api.Test;

class AccountHandlerSqlInjectionBopProofTest {

    @Test
    void ownerParameterCannotWidenTheQuery() throws Exception {
        try (Connection connection = DriverManager.getConnection("jdbc:h2:mem:bop_proof_sqli;DB_CLOSE_DELAY=-1")) {
            try (Statement stmt = connection.createStatement()) {
                stmt.execute("CREATE TABLE accounts (id INT, owner VARCHAR(64))");
                stmt.execute("INSERT INTO accounts VALUES (1, 'alice'), (2, 'bob')");
            }
            AccountHandler handler = new AccountHandler(new AccountService(new AccountRepository(connection)));
            String result = handler.handle(Map.of("owner", "nobody' OR '1'='1"));
            assertEquals("", result,
                "[BOP-PROOF] attacker-controlled owner parameter changed the SQL query and returned other users' accounts");
        }
    }
}

