package com.example.bank.web;

import static org.junit.jupiter.api.Assertions.assertNotEquals;

import com.example.bank.ReportStore;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ReportHandlerPathTraversalBopProofTest {

    @TempDir
    Path tempDir;

    @Test
    void reportNameCannotEscapeTheReportsDirectory() throws Exception {
        Path reports = Files.createDirectory(tempDir.resolve("reports"));
        Files.writeString(tempDir.resolve("secret.txt"), "top secret");
        ReportHandler handler = new ReportHandler(new ReportStore(reports));
        String leaked = null;
        try {
            leaked = handler.handle(Map.of("report", "../secret.txt"));
        } catch (IllegalArgumentException | SecurityException | IOException rejected) {
            // Refusing the request is the safe behaviour.
        }
        assertNotEquals("top secret", leaked,
            "[BOP-PROOF] report name escaped the reports directory and read a file outside it");
    }
}

